import re, subprocess, os

names = []
for root, dirs, files in os.walk("internal"):
    for f in files:
        if f.endswith(".go") and not f.endswith("_test.go"):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()
            for m in re.finditer(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\s*\(', content, re.M):
                names.append((m.group(1), path))

from collections import defaultdict
counts = {}
for name, path in names:
    if len(name) < 4:
        continue
    # count occurrences of name( across whole repo excluding vendor/web
    try:
        out = subprocess.run(["grep", "-rn", "--include=*.go", name+"(", "."], capture_output=True, text=True, timeout=30).stdout
    except Exception:
        continue
    lines = [l for l in out.splitlines() if "/web/" not in l]
    counts[(name, path)] = len(lines)

top = sorted(counts.items(), key=lambda x: -x[1])[:25]
for (name, path), c in top:
    print(c, name, path)
EOF

